// Validate and normalize WF-07 input
const input = $input.first().json || {};

if (!input.scheduled_post_id) {
  throw new Error('MISSING_SCHEDULED_POST_ID');
}

let platforms = input.platforms || [];
if (!Array.isArray(platforms)) platforms = [platforms];
platforms = [...new Set(platforms.map(p => String(p).toLowerCase().trim().replace(/^\s+|\s+$/g, '')))];
platforms = platforms.filter(p => p.length > 0);

const mediaType = (input.media_type || '').toUpperCase();
const supported = ['IMAGE'];
const unsupported = !mediaType ? null : !supported.includes(mediaType);

return [{ json: {
  scheduled_post_id: input.scheduled_post_id,
  title: input.title || null,
  caption: input.caption || null,
  media_type: mediaType || null,
  media_url: input.media_url || null,
  platforms,
  attempt: Number(input.attempt || 1) || 1,
  unsupported_media: unsupported
}}];

// Decide routing based on input
const data = $input.first().json;

// If no platforms -> return empty publication_records immediately
if (!data.platforms || data.platforms.length === 0) {
  return [{
    json: {
      scheduled_post_id: data.scheduled_post_id,
      publication_records: [],
      empty_platforms: true
    },
    output: 0
  }];
}

// If unsupported media -> error record
if (data.unsupported_media) {
  return [{
    json: {
      scheduled_post_id: data.scheduled_post_id,
      media_type: data.media_type,
      attempt: data.attempt,
      platforms: data.platforms,
      unsupported_media: true
    },
    output: 1
  }];
}

// Otherwise -> continue to platform branches (output 2)
return [{
  json: data,
  output: 2
}];

function sanitize(val) {
  const keys = ['access_token','refresh_token','client_secret','authorization',
                'apikey','api_key','secret','password','token'];
  if (Array.isArray(val)) return val.map(sanitize);
  if (val && typeof val === 'object') {
    return Object.fromEntries(
      Object.entries(val).map(([k,v]) => [
        k,
        keys.includes(k.toLowerCase()) ? '[REDACTED]' : sanitize(v)
      ])
    );
  }
  return val;
}
const inData = $input.first().json;
const igErr = inData.ig_error || {};

return [{ json: {
  scheduled_post_id: inData.scheduled_post_id,
  publication_records: [{
    platform: 'instagram',
    status: igErr.status || 'failed',
    success: false,
    external_post_id: null,
    external_publish_id: igErr.creation_id || null,
    external_url: null,
    attempt: inData.attempt || 1,
    error_code: igErr.error_code || 'IG_ERROR',
    error_message: igErr.error_message || igErr.status || 'Instagram operation failed'
  }],
  ig_response_sanitized: sanitize(igErr)
}}];

