const inData = $('03 - Route Input').first().json;

return [{ json: {
  scheduled_post_id: inData.scheduled_post_id,
  publication_records: [{
    platform: 'tiktok',
    status: 'not_configured',
    success: false,
    external_post_id: null,
    external_publish_id: null,
    external_url: null,
    attempt: inData.attempt || 1,
    error_code: 'TIKTOK_NOT_CONFIGURED',
    error_message: 'TikTok publishing is not configured'
  }]
}}];

// Merge all publication_records from all branches
const items = $input.all();
const recordsMap = new Map();

for (const item of items) {
  const recs = item.json.publication_records;
  if (Array.isArray(recs)) {
    for (const r of recs) {
      if (r && r.platform) {
        recordsMap.set(r.platform, r);
      }
    }
  }
}

const records = Array.from(recordsMap.values());

return [{ json: {
  scheduled_post_id: $('02 - Validate/Normalize Input').first().json.scheduled_post_id,
  publication_records: records
}}];

// IG Polling decision with bounded retries
const MAX_ATTEMPTS = 12;
const input = $input.first().json;
const attempts = Number(input.ig_poll_attempts || 0) + 1;

// Load the latest IG status
const statusResp = $('09 - IG Get Status').first().json;
const status = statusResp.status_code || statusResp.status || 'UNKNOWN';

const result = {
  ...input,
  ig_poll_attempts: attempts,
  ig_creation_id: input.ig_creation_id || $('08 - IG Create Media').first().json.id,
  ig_status: status,
  ig_status_message: statusResp.status_message || null,
  ig_media_type: statusResp.media_type || null,
  ig_permalink: statusResp.permalink || null,
  ig_media_url: statusResp.media_url || null,
  ig_timestamp: statusResp.timestamp || null
};

let route;
if (status === 'FINISHED') {
  route = 'publish';
} else if (status === 'ERROR' || status === 'EXPIRED' || status === 'REJECTED') {
  route = 'error';
  result.ig_error = {
    error_code: 'IG_STATUS_' + status,
    error_message: 'Instagram media status: ' + status + (statusResp.status_message ? ' - ' + statusResp.status_message : ''),
    creation_id: result.ig_creation_id,
    status: status
  };
} else if (attempts >= MAX_ATTEMPTS) {
  route = 'error';
  result.ig_error = {
    error_code: 'IG_STATUS_TIMEOUT',
    error_message: 'Instagram media status did not reach FINISHED within ' + MAX_ATTEMPTS + ' polling attempts',
    creation_id: result.ig_creation_id,
    status: status
  };
} else {
  route = 'poll_again';
}

return [{ json: result, output: route === 'poll_again' ? 0 : (route === 'publish' ? 1 : 2) }];

