const record = {
  platform: 'instagram',
  status: 'published',
  success: true,
  external_post_id: pub.id || null,
  external_publish_id: $('10 - IG Poll Decision').first().json.ig_creation_id || null,
  external_url: pub.permalink || null,
  attempt: $input.first().json.attempt || 1,
  error_code: null,
  error_message: null
};

if (pub.id) {
  record.external_post_id = pub.id;
}
if (pub.permalink) {
  record.external_url = pub.permalink;
}

return [{ json: {
  scheduled_post_id: $('02 - Validate/Normalize Input').first().json.scheduled_post_id,
  publication_records: [record],
  ig_response_sanitized: sanitize(pub)
}}];

// Validate Facebook configuration
const auditResp = $('14 - FB Audit Pages').first().json;
const input = $('03 - Route Input').first().json;

const accounts = auditResp.data || [];
if (!accounts || accounts.length === 0) {
  return [{ json: {
    ...input,
    fb_error: {
      error_code: 'FACEBOOK_CONFIGURATION_INCOMPLETE',
      error_message: 'Facebook publisher configuration is incomplete',
      success: false
    }
  }, output: 0}];
}

const hasPublishPerm = accounts.some(a =>
  a.permissions && a.permissions.data &&
  a.permissions.data.some(p =>
    p.permission === 'pages_manage_posts' || p.permission === 'publish_pages'
  )
);

if (!hasPublishPerm) {
  return [{ json: {
    ...input,
    fb_error: {
      error_code: 'FACEBOOK_CONFIGURATION_INCOMPLETE',
      error_message: 'Facebook publisher configuration is incomplete',
      success: false
    }
  }, output: 0}];
}

// Found a valid page - pass through to publishing
const page = accounts[0];
return [{ json: {
  ...input,
  fb_page_id: page.id,
  fb_page_name: page.name,
  fb_page_category: page.category || null
}, output: 1}];

